# Create exactly 17 rows (problem says 17x11)
rows = 17
cols = 11

# I'll construct row by row manually
grid = []
for r in range(rows):
    if r == 0:
        row = [8] * cols
    elif r == 1:
        row = [8, 8, 8, 8, 5, 5, 5, 5, 5, 8, 8]
    elif r == 2:
        row = [8, 8, 8, 8, 5, 7, 7, 7, 5, 8, 8]
    elif r == 3:
        row = [8, 8, 8, 8, 5, 7, 7, 7, 5, 8, 8]
    elif r == 4:
        row = [8, 8, 8, 8, 5, 7, 7, 7, 5, 8, 8]
    elif r == 5:
        row = [9, 9, 9, 8, 5, 5, 5, 5, 5, 8, 8]
    elif r == 6:
        row = [9, 7, 9, 8, 8, 8, 8, 8, 8, 8, 8]
    elif r == 7:
        row = [9, 9, 9, 8, 8, 8, 8, 8, 8, 8, 8]
    else:
        row = [8] * cols

    grid.append(row)

print(f"Grid: {len(grid)} rows x {len(grid[0])} cols")
for i, row in enumerate(grid):
    print(f"Row {i}: {row[:5]}...{row[-5:]}")
